import{_ as p,a0 as r,w as i,s as a,ao as o,I as D,x as u,a1 as e,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧 - 使用Ubuntu拷贝CD和DVD光盘 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧 - 使用Ubuntu拷贝CD和DVD光盘 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧 - 使用Ubuntu拷贝CD和DVD光盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧 - 使用Ubuntu拷贝CD和DVD光盘 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Daily Ubuntu Tips – Copy CD & DVD Discs Using Ubuntu","title":"每日Ubuntu小技巧 - 使用Ubuntu拷贝CD和DVD光盘","tag":"201312","desc":""},"relativePath":"201312/Daily Ubuntu Tips – Copy CD & DVD Discs Using Ubuntu.md","filePath":"[post].md"}'),l={name:"201312/Daily Ubuntu Tips – Copy CD & DVD Discs Using Ubuntu.md"};function b(d,t,C,U,g,V){const n=r("Link");return i(),a("div",null,[t[11]||(t[11]=o('<h1 id="每日ubuntu小技巧-使用ubuntu拷贝cd和dvd光盘" tabindex="-1">每日Ubuntu小技巧 - 使用Ubuntu拷贝CD和DVD光盘 <a class="header-anchor" href="#每日ubuntu小技巧-使用ubuntu拷贝cd和dvd光盘" aria-label="Permalink to “每日Ubuntu小技巧 - 使用Ubuntu拷贝CD和DVD光盘”">​</a></h1><p>Ubuntu是一个功能强大的现代操作系统，可以执行很多任务。你可以使用Ubuntu创建文档，浏览网页，聆听音乐，以及烧录或拷贝媒体光盘。</p><p>就像Windows和Max OS X一样，Ubuntu是无所不能的！</p><p>这篇简单的手册将告诉你如何使用Ubuntu拷贝，翻录或烧录一张CD/DVD光盘。如果你有一张包含音频文件（音乐）或视频文件（电影）的光盘，并且你想要复制这张光盘（创建多个副本），使用Ubuntu会使你很容易做到。</p><p>如果你已经准备好想要拷贝进一张媒体光盘（CD/DVD）的音频或视频文件，Ubuntu也可以处理它。你可以在Ubuntu上安装很多的免费软件用于烧录或翻录一张CD/DVD光盘，但Ubuntu已经安装好一款默认的相关软件。接下来我们会使用这款默认软件去拷贝或翻录CD/DVD光盘。</p><p>Brasero光盘烧录机安装在UBuntu的每一个版本上。它是Ubuntu上默认的光盘烧录机。它被设计得足够简单，拥有诸多独特的特性来使得用户能够快速简便地创建光盘。</p><p>下面列出来的是Brasero的一些特性：</p><ul><li>创建数据CD/DVD时自动过滤隐藏和损坏的文件</li><li>同时支持多个会话，可以执行磁盘文件的完整性检查</li><li>可以即时烧录视频CD/DVD</li><li>可以镜像CD/DVD内容到硬盘</li><li>可以擦除可擦写CD/DVD</li></ul><p>还有很多其它的功能。如果你想找一个Ubuntu上简便的磁盘刻录机，在做任何操作前请先看看这个软件。</p><p>要开始使用Brasero去烧录CD/DVD光盘，请确保你的电脑安装了CD/DVD烧录机。如果没有，显然你无法烧录。如果你的电脑符合要求，将你想要翻录的数据光盘插入CD/DVD，然后进入Dash，搜索Brasero。</p><p>当Brasero打开后，选择磁盘拷贝。这个功能会拷贝一个光盘里的内容，然后将其写入到另一个光盘中。如果这是你想要的，请继续。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/braseroubuntucdburner.png" alt=""></p><p>如果Ubuntu能够访问你的CD/DVD烧录机，Brasero会打开并自动识别光盘内容。在这里，你可以单击 <strong>复制</strong> 从源光盘创建一个拷贝。如果你希望创建多个拷贝，单击按钮 <strong>创建多个拷贝</strong>。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/ubuntubraserocdburner.png" alt=""></p><p>当系统提示安装所需的软件包时，单击 <strong>安装</strong>。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/ubuntubraserocdburner1.png" alt=""></p><p>安装完成后，Brasero会开始拷贝光盘。如果最终光盘完成拷贝，系统会提示你插入一张空白的可写入的CD/DVD光盘以便写入拷贝。插入它然后等待完成将内容写入光盘的操作。</p><p>当你完成以上操作时，移除光盘，就可以使用烧录好的光盘了！</p><hr>',19)),D("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-copy-cd-dvd-discs-using-ubuntu/"},{default:s(()=>[...t[0]||(t[0]=[u("http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-copy-cd-dvd-discs-using-ubuntu/",-1)])]),_:1})]),D("p",null,[t[4]||(t[4]=u("译者：",-1)),e(n,{href:"https://github.com/KayGuoWhu"},{default:s(()=>[...t[2]||(t[2]=[u("KayGuoWhu",-1)])]),_:1}),t[5]||(t[5]=u(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[3]||(t[3]=[u("wxy",-1)])]),_:1})]),D("p",null,[t[8]||(t[8]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[u("Linux中国",-1)])]),_:1}),t[10]||(t[10]=u(" 荣誉推出",-1))])])}const f=p(l,[["render",b]]);export{w as __pageData,f as default};
